INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 17, 'theory', 'Quiz: oVirt architecture');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 17, 0, 'What happens to virtual machines that are already running if the oVirt engine is temporarily unavailable?', '["The hosts will stop all machines", "They keep running, but cannot be managed", "They migrate automatically to a standby engine", "They switch to read-only mode"]', 1, 'Machines are run by the hosts through libvirt and QEMU. The engine only gives orders and keeps the configuration, so its failure removes control but does not stop the machines.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 17, 1, 'What is the correct nesting order of objects in oVirt, from largest to smallest?', '["Cluster, data center, host, VM", "Data center, cluster, host, VM", "Data center, host, cluster, VM", "Host, cluster, data center, VM"]', 1, 'A data center joins shared storage and networks, clusters live inside it, hosts inside clusters, and a machine is tied to a cluster and runs on a host.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 17, 2, 'What role does VDSM play?', '["It stores the engine''s database", "It accepts the engine''s commands on the host and calls libvirt", "It serves the administrator''s web portal", "It chooses the host for starting a machine"]', 1, 'VDSM is the daemon on the host: it carries out the engine''s orders through libvirt, watches storage and network, and reports state. The scheduler in the engine chooses the host.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 17, 3, 'How does a hosted engine differ from a standalone one?', '["It uses no database", "The engine runs as a virtual machine on the hosts it manages", "It manages only one host", "It has no REST interface"]', 1, 'In a hosted engine the engine VM sits on shared storage, and special services restart it on another host after a failure. The database and the API stay the same.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 17, 4, 'What is true of a cluster''s compatibility version?', '["It can be lowered and raised freely", "It can be raised when all hosts and the engine support it", "It only determines an icon color in the portal", "It always equals the host kernel version"]', 1, 'The compatibility version enables a set of features, and it is raised only after every participant is upgraded. The earlier version cannot be restored.');
